fun createChannels(context: Context) {
    // Needed only when minSdk < 26; on API 26+ channels always exist
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return

    val messages = NotificationChannel(
        "messages",                        // stable ID used when posting
        "Messages",                        // name shown in system settings
        NotificationManager.IMPORTANCE_HIGH
    ).apply { description = "New chat messages" }

    context.getSystemService(NotificationManager::class.java)
        .createNotificationChannel(messages)
}

