val launcher = rememberLauncherForActivityResult(
    ActivityResultContracts.RequestPermission()
) { granted -> if (!granted) showNotificationsOffHint() }

if (Build.VERSION.SDK_INT >= 33 &&
    !NotificationManagerCompat.from(context).areNotificationsEnabled()
) {
    launcher.launch(Manifest.permission.POST_NOTIFICATIONS)
}

val tapIntent = TaskStackBuilder.create(context).run {
    // needs android:parentActivityName on ChatActivity in the manifest
    addNextIntentWithParentStack(
        Intent(context, ChatActivity::class.java).putExtra("chatId", chatId)
    )
    getPendingIntent(
        chatId.hashCode(), // unique per chat
        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
    )
}

val notification = NotificationCompat.Builder(context, "messages")
    .setContentIntent(tapIntent)
    .setAutoCancel(true)
    .build()

val manager = NotificationManagerCompat.from(context)

// Same ID: the notification updates in place instead of stacking
